sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

	var ga = new GlideAjax("SharkLearningGlideAjax");
	ga.addParam("sysparm_name", "blockDuplicateTrainings");
	ga.addParam("sysparm_course", g_form.getValue("course"));
	ga.addParam("sysparm_date", g_form.getValue("date"));

	ga.getXMLAnswer(function(response) {
		if(response == "true"){
			g_form.addErrorMessage("Can't create duplicate trainings");
			g_form.setValue("date", "");
		} else{
			g_form.clearMessages();
		}
	});

}
